/**
 * Paperless-ngx's own rules, checked here, before the request is built.
 *
 * ★ THE SAME READER SHAPE AS `../netbox/constraints.ts`, AND FOR THE SAME REASON: both vendors
 *   send a JSON body where a number stays a number and a boolean stays a boolean, so `String(v)`
 *   at the door would be the exact mangling that incident (codegen/README.md) exists to prevent.
 *   The table itself is generated by `bun codegen/paperless.ts` from the vendor's own OpenAPI
 *   document — nothing here is hand-typed.
 *
 * ⚠️ WHAT THIS DELIBERATELY DOES NOT ENFORCE: a `format` name (a DRF validator run server-side); a
 *   pattern the generator could not carry faithfully (codegen/py-pattern.ts), recorded verbatim as
 *   `patternSource`; the `(name, owner)` uniqueness constraint (models.py) — that is `matching.ts`'s
 *   job, not a per-field rule; and `CustomField.select_options`, which is not in the schema at all
 *   (groundTruth: the serializer's own rule is unverified at 3.1.1 and this table cannot state a
 *   rule the vendor document does not carry).
 */

export interface ParamConstraint {
  readonly type?: string;
  /** From the schema's `required` array. ⚠️ Checked on CREATE only. */
  readonly required?: boolean;
  readonly maxLength?: number;
  readonly minLength?: number;
  readonly minimum?: number;
  readonly maximum?: number;
  /** ⚠️ `(string | number)[]` — `matching_algorithm`'s enum is numeric (`DataTypeEnum`'s is not). */
  readonly enum?: readonly (string | number)[];
  readonly pattern?: string;
  readonly patternSource?: string;
  readonly format?: string;
  readonly default?: string;
}

export type EndpointConstraints = Readonly<Record<string, ParamConstraint>>;

/** `paperless:POST /api/tags/` — exactly how the generated tables key an endpoint. */
export type EndpointKey = string;

export type PaperlessBody = Record<string, unknown>;

export interface ViolationOptions {
  /** ⛔ CREATE ONLY. A PATCH is deliberately partial, so presence there refuses every ordinary edit. */
  readonly presence?: boolean;
}

/** ⚠️ `[...value].length`, NOT `value.length` — Django counts characters, JavaScript UTF-16 units. */
const lengthOf = (value: string): number => [...value].length;

const checkString = (name: string, value: string, rule: ParamConstraint): string[] => {
  const out: string[] = [];
  if (rule.maxLength !== undefined && lengthOf(value) > rule.maxLength) {
    out.push(`${name}: at most ${String(rule.maxLength)} characters`);
  }
  if (rule.minLength !== undefined && lengthOf(value) < rule.minLength) {
    out.push(`${name}: at least ${String(rule.minLength)} characters`);
  }
  if (rule.enum !== undefined && !rule.enum.includes(value)) {
    out.push(`${name}: must be one of ${rule.enum.join(', ')}`);
  }
  if (rule.pattern !== undefined && !new RegExp(rule.pattern).test(value)) {
    out.push(`${name}: must match ${rule.patternSource ?? rule.pattern}`);
  }
  return out;
};

const checkNumber = (name: string, value: number, rule: ParamConstraint): string[] => {
  const out: string[] = [];
  if (!Number.isFinite(value)) return out;
  if (rule.minimum !== undefined && value < rule.minimum)
    out.push(`${name}: at least ${String(rule.minimum)}`);
  if (rule.maximum !== undefined && value > rule.maximum)
    out.push(`${name}: at most ${String(rule.maximum)}`);
  return out;
};

const checkValue = (name: string, value: unknown, rule: ParamConstraint): readonly string[] => {
  if (typeof value === 'string') return checkString(name, value, rule);
  if (typeof value === 'number') return checkNumber(name, value, rule);
  return [];
};

/**
 * Every vendor rule this body breaks. Pure — no network, no clock, no environment.
 *
 * ⚠️ `null` IS A VALUE, NOT AN ABSENCE — Paperless uses explicit `null` to clear a nullable
 *   foreign key (`owner`, `parent`), so it must not trip the presence check, and no string/number
 *   rule applies to it.
 */
export const violations = (
  table: EndpointConstraints,
  body: PaperlessBody,
  options: ViolationOptions = {},
): readonly string[] => {
  const out: string[] = [];
  for (const [name, rule] of Object.entries(table)) {
    if (!Object.hasOwn(body, name)) {
      if (options.presence === true && rule.required === true) out.push(`${name}: required`);
      continue;
    }
    const value = body[name];
    for (const item of Array.isArray(value) ? value : [value])
      out.push(...checkValue(name, item, rule));
  }
  return out;
};

/** The message a plan dies with. */
export const refusal = (endpoint: EndpointKey, found: readonly string[]): string =>
  `${endpoint} would be rejected by the vendor:\n  - ${found.join('\n  - ')}\n` +
  "These are Paperless-ngx's own limits, read from its served OpenAPI document " +
  '(packages/alchemy/src/paperless/generated/constraints). Fix the declaration.';
